DELIMITER $$
DROP EVENT IF EXISTS ev_bounty_deadlines$$
CREATE EVENT ev_bounty_deadlines ON SCHEDULE EVERY 1 MINUTE STARTS CURRENT_TIMESTAMP + INTERVAL 1 MINUTE DISABLE DO BEGIN DECLARE done BOOLEAN DEFAULT FALSE; DECLARE entity BIGINT UNSIGNED; DECLARE cur CURSOR FOR SELECT issue_id FROM issues WHERE status NOT IN('RESOLVED','CLOSED') AND is_disputed=FALSE AND bounty_deadline<=SYSDATE(6) ORDER BY issue_id; DECLARE CONTINUE HANDLER FOR NOT FOUND SET done=TRUE; DECLARE CONTINUE HANDLER FOR SQLEXCEPTION BEGIN END; OPEN cur; event_loop: LOOP FETCH cur INTO entity; IF done THEN LEAVE event_loop; END IF; CALL sp_expire_issue(NULL,CONCAT(LEFT(MD5(CONCAT('bounty_deadlines',entity)),32),'0000'),JSON_OBJECT('issue_id',entity),@job_result); END LOOP; CLOSE cur; END$$
DROP EVENT IF EXISTS ev_claim_expiry$$
CREATE EVENT ev_claim_expiry ON SCHEDULE EVERY 1 MINUTE STARTS CURRENT_TIMESTAMP + INTERVAL 1 MINUTE DISABLE DO BEGIN DECLARE done BOOLEAN DEFAULT FALSE; DECLARE entity BIGINT UNSIGNED; DECLARE cur CURSOR FOR SELECT claim_id FROM claims WHERE status='ACTIVE' AND expires_at<=SYSDATE(6) ORDER BY claim_id; DECLARE CONTINUE HANDLER FOR NOT FOUND SET done=TRUE; DECLARE CONTINUE HANDLER FOR SQLEXCEPTION BEGIN END; OPEN cur; event_loop: LOOP FETCH cur INTO entity; IF done THEN LEAVE event_loop; END IF; CALL sp_expire_claim(NULL,CONCAT(LEFT(MD5(CONCAT('claim_expiry',entity)),32),'0000'),JSON_OBJECT('claim_id',entity),@job_result); END LOOP; CLOSE cur; END$$
DELIMITER ;
